@push('scripts')<script>
document.getElementById('generer-plan-ia').addEventListener('click',async function(){const feedback=document.getElementById('plan-ia-message');this.disabled=true;feedback.textContent='Génération en cours…';try{const main=document.querySelector('form[action*="plans-urgence"]');const value=n=>main.querySelector(`[name="${n}"]`)?.value||'';const response=await fetch('{{ route('admin.plans-urgence.ia') }}',{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':main.querySelector('[name="_token"]').value},body:JSON.stringify({action:'generer',type_evenement:value('type_evenement'),niveau_risque:value('niveau_risque'),public_cible:value('public_cible')})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat().join(' '));const fields=document.getElementById('plan-ia-champs');fields.replaceChildren();[['type_evenement',value('type_evenement')],['niveau_risque',value('niveau_risque')],['public_cible',value('public_cible')]].forEach(([name,val])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=val;fields.append(input);});const titre=document.createElement('input');titre.className='form-control mb-2';titre.name='titre';titre.value=data.titre;const description=document.createElement('textarea');description.className='form-control mb-3';description.name='description';description.value=data.description;fields.append(titre,description);const table=document.createElement('table');table.className='table';const head=document.createElement('thead');head.innerHTML='<tr><th>Titre</th><th>Description</th><th>Moment</th><th>Obligatoire</th></tr>';table.append(head);const body=document.createElement('tbody');data.etapes.forEach((step,i)=>{const row=document.createElement('tr');[['titre',step.titre],['description',step.description||''],['moment',step.moment],['obligatoire',step.obligatoire?'1':'0']].forEach(([name,val])=>{const cell=document.createElement('td');const input=document.createElement('input');input.className='form-control';input.name=`etapes[${i}][${name}]`;input.value=val;if(name==='obligatoire'){const hidden=document.createElement('input');hidden.type='hidden';hidden.name=input.name;hidden.value=val;input.removeAttribute('name');input.type='checkbox';input.checked=val==='1';input.value='1';input.addEventListener('change',()=>hidden.value=input.checked?'1':'0');cell.append(hidden);}cell.append(input);row.append(cell);});body.append(row);});table.append(body);fields.append(table);document.getElementById('plan-ia-enregistrer').classList.remove('d-none');feedback.textContent='Modifiez les champs proposés avant de créer le plan.';}catch(e){feedback.textContent=e.message;}finally{this.disabled=false;}});
</script>@endpush @endif
